const __pageData = JSON.parse('{"title":"Joe Biden","description":"","frontmatter":{"title":"Joe Biden","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["senator","crime-bill",1994],"sources":["raw/a-journey-of-ever-changing-truths.md","raw/a-time-to-strike.md","raw/a-week-to-remember.md","raw/and-iran-iran-so-far-away.md","raw/are-we-being-distracted.md","raw/assad-day-in-damascus.md","raw/badlands-brief-1ae.md","raw/badlands-brief-7bf.md","raw/badlands-brief-c91.md","raw/badlands-news-brief-017.md","raw/badlands-news-brief-050.md","raw/badlands-news-brief-024.md","raw/badlands-news-brief-070.md","raw/badlands-news-brief-01d.md","raw/badlands-news-brief-08c.md","raw/badlands-news-brief-082.md","raw/badlands-news-brief-092.md","raw/badlands-news-brief-071.md","raw/badlands-news-brief-07e.md","raw/badlands-news-brief-099.md","raw/badlands-news-brief-09e.md","raw/badlands-news-brief-0db.md","raw/badlands-news-brief-0c1.md","raw/badlands-news-brief-051.md","raw/badlands-news-brief-0f0.md","raw/badlands-news-brief-0ad.md","raw/badlands-news-brief-10a.md","raw/badlands-news-brief-11c.md","raw/badlands-news-brief-116.md","raw/badlands-news-brief-125.md","raw/badlands-news-brief-120.md","raw/badlands-news-brief-13f.md","raw/badlands-news-brief-12a.md","raw/badlands-news-brief-138.md","raw/badlands-news-brief-148.md","raw/badlands-news-brief-169.md","raw/badlands-news-brief-19b.md","raw/badlands-news-brief-18e.md","raw/badlands-news-brief-1c3.md","raw/badlands-news-brief-1e2.md","raw/badlands-news-brief-1a7.md","raw/badlands-news-brief-1d1.md","raw/badlands-news-brief-1cc.md","raw/badlands-news-brief-204.md","raw/badlands-news-brief-214.md","raw/badlands-news-brief-25f.md","raw/badlands-news-brief-26c.md","raw/badlands-news-brief-264.md","raw/badlands-news-brief-28e.md","raw/badlands-news-brief-24e.md","raw/badlands-news-brief-2ad.md","raw/badlands-news-brief-2db.md","raw/badlands-news-brief-2d2.md","raw/badlands-news-brief-33b.md","raw/badlands-news-brief-351.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-384.md","raw/badlands-news-brief-3ae.md","raw/badlands-news-brief-3f0.md","raw/badlands-news-brief-423.md","raw/badlands-news-brief-433.md","raw/badlands-news-brief-42e.md","raw/badlands-news-brief-447.md","raw/badlands-news-brief-46e.md","raw/badlands-news-brief-4a6.md","raw/badlands-news-brief-4b3.md","raw/badlands-news-brief-4b9.md","raw/badlands-news-brief-505.md","raw/badlands-news-brief-4c5.md","raw/badlands-news-brief-533.md","raw/badlands-news-brief-565.md","raw/badlands-news-brief-5a7.md","raw/badlands-news-brief-617.md","raw/badlands-news-brief-5fb.md","raw/badlands-news-brief-61a.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-6c4.md","raw/badlands-news-brief-69b.md","raw/badlands-news-brief-6f0.md","raw/badlands-news-brief-6fc.md","raw/badlands-news-brief-644.md","raw/badlands-news-brief-711.md","raw/badlands-news-brief-677.md","raw/badlands-news-brief-670.md","raw/badlands-news-brief-669.md","raw/badlands-news-brief-67e.md","raw/badlands-news-brief-782.md","raw/badlands-news-brief-786.md","raw/badlands-news-brief-7b1.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-7a7.md","raw/badlands-news-brief-7bf.md","raw/badlands-news-brief-7c6.md","raw/badlands-news-brief-845.md","raw/badlands-news-brief-881.md","raw/badlands-news-brief-8ae.md","raw/badlands-news-brief-860.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/joe-biden.md","filePath":"entities/joe-biden.md","lastUpdated":null}');
